export class UIManager{constructor({time,company,quests,dialogue,player,world}){this.time=time;this.company=company;this.quests=quests;this.dialogue=dialogue;this.player=player;this.world=world;this.root=document.getElementById("ui-root");this.mounted=false;this.notifications=0}mount(){if(!this.root)return;this.root.innerHTML=`<div class="hud"><div class="hud-left"><div class="hud-card"><div class="hud-title">Founder</div><div class="hud-value">❤️ 100</div></div><div class="hud-card"><div class="hud-title">Cash</div><div id="cash" class="hud-value">$10,000</div></div><div class="hud-card"><div class="hud-title">Rep</div><div id="rep" class="hud-value">⭐ 5</div></div></div><div class="hud-right"><div class="hud-card"><div class="hud-title">Time</div><div id="clock" class="hud-value">08:00</div></div><div class="hud-card"><div class="hud-title">City</div><div id="period" class="hud-value">Morning</div></div></div></div><div id="quest-panel" class="quest-panel"></div><div id="interaction" class="interaction" style="display:none">Press E to interact</div><div id="dialogue-root"></div>`;this.mounted=true;this.dialogue.attachUI(this);this.quests.attachUI(this);this.update()}update(){if(!this.mounted)return;const q=this.quests.currentQuest,p=this.quests.progress[q?.id]||{};const clock=this.root.querySelector("#clock"),period=this.root.querySelector("#period"),cash=this.root.querySelector("#cash"),rep=this.root.querySelector("#rep");if(clock)clock.textContent=this.time.formatted;if(period)period.textContent=this.time.period[0].toUpperCase()+this.time.period.slice(1);if(cash)cash.textContent="$"+this.company.cash.toLocaleString("en-US");if(rep)rep.textContent="⭐ "+this.company.reputation;this.renderQuest(q,p);const i=this.root.querySelector("#interaction");if(i)i.style.display=this.player.interactionTarget&&!this.dialogue.active?"block":"none"}renderQuest(q,p){const panel=this.root.querySelector("#quest-panel");if(!panel)return;if(!q){panel.innerHTML=`<div class="quest-label">Journey Complete</div><div class="quest-title">Your MVP is live!</div><div class="quest-description">The startup journey has begun. More gameplay is coming in v0.6.</div>`;return}const o=q.objectives.find(x=>(p[x.id]||0)<x.required)||q.objectives[q.objectives.length-1],done=p[o.id]||0;panel.innerHTML=`<div class="quest-label">Active Quest</div><div class="quest-title">${q.title}</div><div class="quest-description">${q.description}</div><div class="quest-objective">${o.label} (${done}/${o.required})</div><div class="quest-progress"><div class="quest-progress-fill" style="width:${Math.min(100,done/o.required*100)}%"></div></div>`}showDialogue(name,lines,onClose){const r=this.root.querySelector("#dialogue-root");r.innerHTML=`<div class="dialogue-backdrop"></div><div class="dialogue"><div class="dialogue-name">${name}</div><div class="dialogue-text">${lines[0]}</div><div class="dialogue-actions"><button class="dialogue-button" id="dialogue-next">Continue</button></div></div>`;let i=0;const text=r.querySelector(".dialogue-text"),button=r.querySelector("#dialogue-next");button.onclick=()=>{i++;if(i>=lines.length){onClose();return}text.textContent=lines[i];if(i===lines.length-1)button.textContent="Close"}}hideDialogue(){this.root.querySelector("#dialogue-root").innerHTML=""}notify(message){const n=document.createElement("div");n.className="notification";n.style.top=`${95+this.notifications*55}px`;this.notifications++;n.textContent=message;this.root.appendChild(n);setTimeout(()=>{n.remove();this.notifications=Math.max(0,this.notifications-1)},2600)}getLocation(id){return this.world.locations.find(l=>l.id===id)}draw(){}}
